import{_ as i,o as s,c as t,a2 as a}from"./chunks/framework.qEx7tieT.js";const k=JSON.parse('{"title":"Importing IFC","description":"","frontmatter":{},"headers":[],"relativePath":"tools/ifc.md","filePath":"tools/ifc.md"}'),n={name:"tools/ifc.md"};function o(r,e,h,c,l,d){return s(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="importing-ifc" tabindex="-1">Importing IFC <a class="header-anchor" href="#importing-ifc" aria-label="Permalink to &quot;Importing IFC&quot;">​</a></h1><p><code>mosaic</code> converts an IFC model the same way, reading <code>.ifc</code> files of either IFC4 or IFC2X3:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mosaic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ifc</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">      &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">input.if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [output.mosaic.json] [--center] [--no-geometry] [--seed</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">text</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mosaic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ifc-pack</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">input.if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [output.tsr]         [--center] [--no-geometry] [--seed</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">text</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>Parsing and meshing are <a href="https://github.com/ThatOpen/engine_web-ifc" target="_blank" rel="noreferrer">web-ifc</a>&#39;s job: it resolves placements, subtracts openings and tessellates, and reports the result in metres and Y-up, which is already glTF&#39;s convention. What the converter does is decide what all of it becomes in Mosaic.</p><p>The spatial tree becomes the node tree. IFC says the hierarchy with relationship objects like every other fact — a storey holds its walls through an <code>IfcRelContainedInSpatialStructure</code> — but Mosaic has a parent-child link that a viewer, a selection and a composition all read, so <code>IfcRelAggregates</code>, <code>IfcRelNests</code> and <code>IfcRelContainedInSpatialStructure</code> become <code>core::child</code>.</p><p>Everything else becomes a component. <code>ifc4::entity</code> carries the class, the <code>GlobalId</code> and every direct attribute; <code>ifc4::propertySet</code> and <code>ifc4::quantitySet</code> carry the properties and the measured numbers; <code>ifc4::units</code> says what the file&#39;s numbers are in. Every remaining relationship gets a component type of its own — <code>ifc4::rel::IfcRelDefinesByType</code>, <code>ifc4::rel::IfcRelVoidsElement</code>, one table per class — and the link is the <em>reference</em>: the component sits on the related node and its reference name is the id of the node at the other end. One row serves every link a relationship makes, so an aggregate with four hundred parts is one row and four hundred references.</p><p>A node&#39;s id comes from <code>IfcRoot.GlobalId</code>, so re-exporting the model from the authoring tool and converting it again leaves every id another archive was pointing at exactly where it was.</p><p>The conversion lives in its own package, <a href="https://github.com/tomvandig/mosaic/tree/main/sdk/ifc4/" target="_blank" rel="noreferrer"><code>sdk/ifc4/</code></a>, which <a href="https://github.com/tomvandig/mosaic/blob/main/sdk/ifc4/README.md" target="_blank" rel="noreferrer">documents the mapping in full</a>.</p>`,8)])])}const g=i(n,[["render",o]]);export{k as __pageData,g as default};
